static double relu(double value)
{
	return value > 0.0 ? value : 0.0;
}

static void calculateMlpResidualCompensationCore(
	const double* q, const double* dq, const double* ddq, double* residual)
{
	double features[kMlpInputDim];
	features[0] = q[0];
	features[1] = dq[0];
	features[2] = ddq[0];
	features[3] = q[1];
	features[4] = dq[1];
	features[5] = ddq[1];
	features[6] = q[2];
	features[7] = dq[2];
	features[8] = ddq[2];
	features[9] = q[3];
	features[10] = dq[3];
	features[11] = ddq[3];
	features[12] = q[4];
	features[13] = dq[4];
	features[14] = ddq[4];
	features[15] = q[5];
	features[16] = dq[5];
	features[17] = ddq[5];
	features[18] = q[6];
	features[19] = dq[6];
	features[20] = ddq[6];
	features[21] = fabs(dq[0]);
	features[22] = fabs(ddq[0]);
	features[23] = q[0] * dq[0];
	features[24] = sin(q[0]);
	features[25] = cos(q[0]);
	features[26] = fabs(dq[1]);
	features[27] = fabs(ddq[1]);
	features[28] = q[1] * dq[1];
	features[29] = sin(q[1]);
	features[30] = cos(q[1]);
	features[31] = fabs(dq[2]);
	features[32] = fabs(ddq[2]);
	features[33] = q[2] * dq[2];
	features[34] = sin(q[2]);
	features[35] = cos(q[2]);
	features[36] = fabs(dq[3]);
	features[37] = fabs(ddq[3]);
	features[38] = q[3] * dq[3];
	features[39] = sin(q[3]);
	features[40] = cos(q[3]);
	features[41] = fabs(dq[4]);
	features[42] = fabs(ddq[4]);
	features[43] = q[4] * dq[4];
	features[44] = sin(q[4]);
	features[45] = cos(q[4]);
	features[46] = fabs(dq[5]);
	features[47] = fabs(ddq[5]);
	features[48] = q[5] * dq[5];
	features[49] = sin(q[5]);
	features[50] = cos(q[5]);
	features[51] = fabs(dq[6]);
	features[52] = fabs(ddq[6]);
	features[53] = q[6] * dq[6];
	features[54] = sin(q[6]);
	features[55] = cos(q[6]);
	features[56] = dq[0] * dq[1];
	features[57] = dq[1] * dq[2];
	features[58] = dq[2] * dq[3];
	features[59] = dq[3] * dq[4];
	features[60] = dq[4] * dq[5];
	features[61] = dq[5] * dq[6];
	features[62] = sqrt(dq[0] * dq[0] + dq[1] * dq[1] + dq[2] * dq[2] + dq[3] * dq[3] + dq[4] * dq[4] + dq[5] * dq[5] + dq[6] * dq[6]);
	double h0[kMlpLayer0Dim];
	for (int outIdx = 0; outIdx < kMlpLayer0Dim; ++outIdx)
	{
		double value = kMlpB0[outIdx];
		for (int inIdx = 0; inIdx < kMlpInputDim; ++inIdx)
		{
			const double normalized = (features[inIdx] - kMlpXMean[inIdx]) / kMlpXScale[inIdx];
			value += normalized * kMlpW0[inIdx][outIdx];
		}
		h0[outIdx] = relu(value);
	}
	double h1[kMlpLayer1Dim];
	for (int outIdx = 0; outIdx < kMlpLayer1Dim; ++outIdx)
	{
		double value = kMlpB1[outIdx];
		for (int inIdx = 0; inIdx < kMlpLayer0Dim; ++inIdx)
		{
			value += h0[inIdx] * kMlpW1[inIdx][outIdx];
		}
		h1[outIdx] = relu(value);
	}
	for (int outIdx = 0; outIdx < kMlpOutputDim; ++outIdx)
	{
		double value = kMlpB2[outIdx];
		for (int inIdx = 0; inIdx < kMlpLayer1Dim; ++inIdx)
		{
			value += h1[inIdx] * kMlpW2[inIdx][outIdx];
		}
		residual[outIdx] = value * kMlpYScale[outIdx] + kMlpYMean[outIdx];
	}
}

// -----------------------------------------------------------------------------
// RTOSAlgorithm-style class implementation
// -----------------------------------------------------------------------------

sevendofDynamics::sevendofDynamics()
{
	m_NumJoints = 7;
	m_gx = 9.8100000000000005;
	m_gy = 0;
	m_gz = 0;
	m_zeros.assign(m_NumJoints, 0.0);
}

sevendofDynamics::~sevendofDynamics()
{
}

void sevendofDynamics::setRobotDHParameters
(
	const EcRealVector& kinematcisParam
)
{
	// Geometry is fixed by the URDF used during code generation.
	// Keep this method for compatibility with dynamicsBase callers.
	(void)kinematcisParam;
}

void sevendofDynamics::setGravityVector
(
	const EcReal gx, const EcReal gy, const EcReal gz
)
{
	m_gx = gx;
	m_gy = gy;
	m_gz = gz;
}

void sevendofDynamics::calculateGravityJointTorques
(
	const EcRealVector& q,
	const EcRealVector& parms,
	EcRealVector& tau
)
{
	calculateEstimateJointToqrues(q, m_zeros, m_zeros, parms, tau);
}

EcBoolean sevendofDynamics::calculateEstimateJointToqrues
(
	const EcRealVector& q,
	const EcRealVector& dq,
	const EcRealVector& ddq,
	const EcRealVector& parms,
	EcRealVector& tau
)
{
	(void)parms;  // Identified parameters are baked into the generated formula.
	if (q.size() != m_NumJoints || dq.size() != m_NumJoints || ddq.size() != m_NumJoints)
	{
		return false;
	}
	if (tau.size() != m_NumJoints)
	{
		tau.assign(m_NumJoints, 0.0);
	}

	const double gravity[3] = {m_gx, m_gy, m_gz};
	calculateIdentifiedInverseDynamicsCore(q.data(), dq.data(), ddq.data(), gravity, tau.data());
	double residual[kNumJoints];
	calculateMlpResidualCompensationCore(q.data(), dq.data(), ddq.data(), residual);
	for (EcSizeT jointIdx = 0; jointIdx < m_NumJoints; ++jointIdx)
	{
		tau[jointIdx] += residual[jointIdx];
	}
	return true;
}

void sevendofDynamics::calculateMomentumEstimatedJointTorques
(
	const EcRealVector& q,
	const EcRealVector& dq,
	const EcRealVector& ddq,
	const EcRealVector& parms,
	EcRealVector& tau
)
{
	(void)parms;
	if (q.size() != m_NumJoints || dq.size() != m_NumJoints || ddq.size() != m_NumJoints)
	{
		return;
	}
	if (tau.size() != m_NumJoints)
	{
		tau.assign(m_NumJoints, 0.0);
	}

	const double zeroGravity[3] = {0.0, 0.0, 0.0};
	calculateIdentifiedRigidDynamicsCore(q.data(), dq.data(), ddq.data(), zeroGravity, tau.data());
}
